#define NOMINMAX
#define WIN32_LEAN_AND_MEAN
#include <windows.h>
#include "debug_view.h"
#include "debug_view_cs.h" // generated by build.bat (dxc -Fh), defines g_debug_view_cs

#include <atomic>
#include <cstdio>
#include <mutex>

void logf(const char *fmt, ...);

namespace debug_view
{
	static const char *const k_names[] = {
		"off", "diffuse albedo", "normal", "roughness", "RT6 as color", "RT7 as color", "material flags", "resolved F0 (RT4.a scalar)", "RT4 alpha", "RT5 rgb", "RT5 alpha", "resolved F0 (RT5.a scalar)" };
	static constexpr int k_mode_count = sizeof(k_names) / sizeof(k_names[0]);
	static constexpr UINT k_desc_per_frame = 7; // 6 SRV + 1 UAV
	static constexpr UINT k_frames = 4;

	static std::atomic<int> s_mode{0};
	static ID3D12Device *s_device = nullptr;
	static ID3D12RootSignature *s_rootsig = nullptr;
	static ID3D12PipelineState *s_pso = nullptr;
	static ID3D12DescriptorHeap *s_heap = nullptr;
	static UINT s_inc = 0;
	static UINT s_frame = 0;
	static bool s_failed = false;

	static std::mutex s_mtx;
	static ID3D12Resource *s_rt[8] = {};
	static std::atomic<bool> s_drawn_this_frame{false};

	int mode() { return s_mode.load(); }
	const char *mode_name(int m) { return m >= 0 && m < k_mode_count ? k_names[m] : "?"; }
	void next_mode()
	{
		const int m = (s_mode.load() + 1) % k_mode_count;
		s_mode = m;
		logf("debug view: %d (%s)", m, k_names[m]);
	}

	void on_device(ID3D12Device *device)
	{
		// Follow the newest device (see rr::on_device); objects from an older device are dropped.
		if (!device || device == s_device) return;
		std::lock_guard lock(s_mtx);
		s_device = device;
		s_rootsig = nullptr; s_pso = nullptr; s_heap = nullptr; s_failed = false;
		for (auto &r : s_rt) r = nullptr;
	}

	void on_gbuffer(ID3D12Resource *const rts[8])
	{
		std::lock_guard lock(s_mtx);
		for (int i = 0; i < 8; ++i) s_rt[i] = rts[i];
	}

	void new_frame() { s_drawn_this_frame = false; }

	static bool init()
	{
		if (s_pso) return true;
		if (s_failed || !s_device) return false;
		s_failed = true; // only try once

		using PFN_Serialize = HRESULT(WINAPI *)(const D3D12_ROOT_SIGNATURE_DESC *, D3D_ROOT_SIGNATURE_VERSION, ID3DBlob **, ID3DBlob **);
		auto serialize = reinterpret_cast<PFN_Serialize>(GetProcAddress(GetModuleHandleW(L"d3d12.dll"), "D3D12SerializeRootSignature"));
		if (!serialize) { logf("debug view: D3D12SerializeRootSignature missing"); return false; }

		D3D12_DESCRIPTOR_RANGE ranges[2] = {};
		ranges[0] = { D3D12_DESCRIPTOR_RANGE_TYPE_SRV, 6, 0, 0, 0 };
		ranges[1] = { D3D12_DESCRIPTOR_RANGE_TYPE_UAV, 1, 0, 0, 0 };
		D3D12_ROOT_PARAMETER params[3] = {};
		params[0].ParameterType = D3D12_ROOT_PARAMETER_TYPE_32BIT_CONSTANTS;
		params[0].Constants = { 0, 0, 8 };
		params[1].ParameterType = D3D12_ROOT_PARAMETER_TYPE_DESCRIPTOR_TABLE;
		params[1].DescriptorTable = { 1, &ranges[0] };
		params[2].ParameterType = D3D12_ROOT_PARAMETER_TYPE_DESCRIPTOR_TABLE;
		params[2].DescriptorTable = { 1, &ranges[1] };
		const D3D12_ROOT_SIGNATURE_DESC rsd = { 3, params, 0, nullptr, D3D12_ROOT_SIGNATURE_FLAG_NONE };
		ID3DBlob *blob = nullptr, *err = nullptr;
		if (FAILED(serialize(&rsd, D3D_ROOT_SIGNATURE_VERSION_1, &blob, &err)))
		{
			logf("debug view: root signature serialize failed: %s", err ? (const char *)err->GetBufferPointer() : "?");
			if (err) err->Release();
			return false;
		}
		HRESULT hr = s_device->CreateRootSignature(0, blob->GetBufferPointer(), blob->GetBufferSize(), IID_PPV_ARGS(&s_rootsig));
		blob->Release();
		if (FAILED(hr)) { logf("debug view: CreateRootSignature failed 0x%08lx", hr); return false; }

		D3D12_COMPUTE_PIPELINE_STATE_DESC pd = {};
		pd.pRootSignature = s_rootsig;
		pd.CS = { g_debug_view_cs, sizeof(g_debug_view_cs) };
		hr = s_device->CreateComputePipelineState(&pd, IID_PPV_ARGS(&s_pso));
		if (FAILED(hr)) { logf("debug view: CreateComputePipelineState failed 0x%08lx", hr); return false; }

		const D3D12_DESCRIPTOR_HEAP_DESC hd = { D3D12_DESCRIPTOR_HEAP_TYPE_CBV_SRV_UAV, k_desc_per_frame * k_frames, D3D12_DESCRIPTOR_HEAP_FLAG_SHADER_VISIBLE, 0 };
		hr = s_device->CreateDescriptorHeap(&hd, IID_PPV_ARGS(&s_heap));
		if (FAILED(hr)) { logf("debug view: CreateDescriptorHeap failed 0x%08lx", hr); s_pso->Release(); s_pso = nullptr; return false; }
		s_inc = s_device->GetDescriptorHandleIncrementSize(D3D12_DESCRIPTOR_HEAP_TYPE_CBV_SRV_UAV);

		s_failed = false;
		logf("debug view: initialized (F8 cycles modes)");
		return true;
	}

	static void write_srv(D3D12_CPU_DESCRIPTOR_HANDLE h, ID3D12Resource *res, DXGI_FORMAT fmt)
	{
		D3D12_SHADER_RESOURCE_VIEW_DESC d = {};
		d.Format = fmt;
		d.ViewDimension = D3D12_SRV_DIMENSION_TEXTURE2D;
		d.Shader4ComponentMapping = D3D12_DEFAULT_SHADER_4_COMPONENT_MAPPING;
		d.Texture2D.MipLevels = 1;
		s_device->CreateShaderResourceView(res, &d, h);
	}

	bool draw_ldr(ID3D12GraphicsCommandList *cmd, ID3D12Resource *color)
	{
		const int m = s_mode.load();
		if (m == 0 || !cmd || !color || s_drawn_this_frame.load() || !init()) return false;

		ID3D12Resource *rt[8];
		{
			std::lock_guard lock(s_mtx);
			memcpy(rt, s_rt, sizeof(rt));
		}
		if (!rt[3]) return false;
		const D3D12_RESOURCE_DESC src_desc = rt[3]->GetDesc();
		const D3D12_RESOURCE_DESC dst_desc = color->GetDesc();
		if (!(dst_desc.Flags & D3D12_RESOURCE_FLAG_ALLOW_UNORDERED_ACCESS))
		{
			static bool warned = false;
			if (!warned) { warned = true; logf("debug view: target %p (fmt %u) has no UAV flag, skipped", color, (unsigned)dst_desc.Format); }
			return false;
		}
		s_drawn_this_frame = true;
		const unsigned sw = (unsigned)src_desc.Width, sh = src_desc.Height, w = (unsigned)dst_desc.Width, h = dst_desc.Height;
		const unsigned state = D3D12_RESOURCE_STATE_RENDER_TARGET;

		const UINT base = (s_frame++ % k_frames) * k_desc_per_frame;
		D3D12_CPU_DESCRIPTOR_HANDLE cpu = s_heap->GetCPUDescriptorHandleForHeapStart();
		D3D12_GPU_DESCRIPTOR_HANDLE gpu = s_heap->GetGPUDescriptorHandleForHeapStart();
		cpu.ptr += SIZE_T(base) * s_inc; gpu.ptr += UINT64(base) * s_inc;
		auto at = [&](UINT i) { D3D12_CPU_DESCRIPTOR_HANDLE c = cpu; c.ptr += SIZE_T(i) * s_inc; return c; };

		write_srv(at(0), rt[3], DXGI_FORMAT_R32_UINT);
		write_srv(at(1), rt[4], DXGI_FORMAT_R8G8B8A8_UNORM_SRGB);
		write_srv(at(2), rt[6], DXGI_FORMAT_R32_UINT);
		write_srv(at(3), rt[7], DXGI_FORMAT_R32_UINT);
		write_srv(at(4), rt[2], DXGI_FORMAT_R8G8B8A8_UINT);
		write_srv(at(5), rt[5], DXGI_FORMAT_R8G8B8A8_UNORM);
		D3D12_UNORDERED_ACCESS_VIEW_DESC ud = {};
		ud.Format = dst_desc.Format == DXGI_FORMAT_R8G8B8A8_TYPELESS ? DXGI_FORMAT_R8G8B8A8_UNORM : dst_desc.Format;
		ud.ViewDimension = D3D12_UAV_DIMENSION_TEXTURE2D;
		s_device->CreateUnorderedAccessView(color, nullptr, &ud, at(6));

		const D3D12_RESOURCE_STATES before = static_cast<D3D12_RESOURCE_STATES>(state);
		D3D12_RESOURCE_BARRIER b = {};
		b.Type = D3D12_RESOURCE_BARRIER_TYPE_TRANSITION;
		b.Transition.pResource = color;
		b.Transition.Subresource = D3D12_RESOURCE_BARRIER_ALL_SUBRESOURCES;
		b.Transition.StateBefore = before;
		b.Transition.StateAfter = D3D12_RESOURCE_STATE_UNORDERED_ACCESS;
		if (before != D3D12_RESOURCE_STATE_UNORDERED_ACCESS) cmd->ResourceBarrier(1, &b);

		ID3D12DescriptorHeap *heaps[] = { s_heap };
		cmd->SetDescriptorHeaps(1, heaps);
		cmd->SetComputeRootSignature(s_rootsig);
		cmd->SetPipelineState(s_pso);
		const UINT consts[8] = { (UINT)m, sw, sh, w, h, 0, 0, 0 };
		cmd->SetComputeRoot32BitConstants(0, 8, consts, 0);
		D3D12_GPU_DESCRIPTOR_HANDLE srv = gpu, uav = gpu; uav.ptr += UINT64(6) * s_inc;
		cmd->SetComputeRootDescriptorTable(1, srv);
		cmd->SetComputeRootDescriptorTable(2, uav);
		cmd->Dispatch((w + 7) / 8, (h + 7) / 8, 1);

		D3D12_RESOURCE_BARRIER after = {};
		after.Type = D3D12_RESOURCE_BARRIER_TYPE_UAV;
		after.UAV.pResource = color;
		cmd->ResourceBarrier(1, &after);
		if (before != D3D12_RESOURCE_STATE_UNORDERED_ACCESS)
		{
			std::swap(b.Transition.StateBefore, b.Transition.StateAfter);
			cmd->ResourceBarrier(1, &b);
		}

		static bool logged = false;
		if (!logged) { logged = true; logf("debug view: first draw %ux%u -> %ux%u (fmt %u) mode %d", sw, sh, w, h, (unsigned)dst_desc.Format, m); }
		return true;
	}
}
